-- Pre/Post SQL hooks: the orchestration task may override these defaults at runtime via dbt --vars.
{% set pre_sql = var('m_MT_RSTD_BKGS_PID_SL6_FWEEK_sq_mt_rstd_bkgs_measure_pre_sql', '') %}
{% if pre_sql != '' %}
  {{ config(pre_hook=pre_sql) }}
{% endif %}
{% if var('m_MT_RSTD_BKGS_PID_SL6_FWEEK_sq_mt_rstd_bkgs_measure_sql_override', '') != '' %}
{{ var('m_MT_RSTD_BKGS_PID_SL6_FWEEK_sq_mt_rstd_bkgs_measure_sql_override') }}
{% else %}
-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
 RFWTY.FISCAL_YEAR_WEEK_NUM_INT,
 NBM.PRODUCT_KEY,
 NBCM.PARTNER_SITE_PARTY_KEY,
 NBM.SALES_TERRITORY_KEY,
 NBM.ADJUSTMENT_TYPE_CODE AS ADJUSTMENT_TYPE_CD,
 NBM.SALES_CHANNEL_CODE AS SALES_CHANNEL_CD,
 NBM.SALES_CREDIT_TYPE_CODE AS SALES_CREDIT_TYPE_CD,
 NBM.IDE_ADJUSTMENT_CODE AS IDE_ADJUSTMENT_CD,
 NBM.ADJUSTMENT_CODE AS ADJUSTMENT_CD,
 NBM.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
 NBM.CANCELLED_FLG,
 NBM.ACQUISITION_FLG,
 NBM.DISTRIBUTOR_OFFSET_FLG,
 NBM.CORPORATE_BOOKINGS_FLG,
 NBCM.CHANNEL_BOOKINGS_FLG,
 NBM.OVERLAY_FLG,
 NBM.IC_REVENUE_FLG,
 NBM.CHARGES_FLG,
 NBM.SALESREP_FLG,
 NBM.MISC_FLG,
 NBM.SERVICE_FLG,
 NBM.INTERNATIONAL_DEMO_FLG,
 NBM.REPLACEMENT_DEMO_FLG,
 NBM.REVENUE_FLG,
 NBM.RMA_FLG,
 NBM.WIPS_ORIGINATOR_ID_INT,
 'UNKNOWN' DV_DISCOUNT_BAND_CD,
 'UNKNOWN' DV_ORDER_BAND_CD,
 CASE
  WHEN COLLATE(NBM.SERVICE_FLG, 'en-ci-rtrim') = 'N'
   THEN 'PRODUCT'
  WHEN COLLATE(NBM.SERVICE_FLG, 'en-ci-rtrim') = 'Y' AND RTRIM( NPT.BK_PRODUCT_TYPE_ID) NOT IN (COLLATE('TECHDOC', 'en-ci-rtrim'), COLLATE('TRAINING', 'en-ci-rtrim'))
   THEN 'CA SERVICE'
    ELSE 'OTHER SERVICE'
 END AS DV_CA_BOOKINGS_TYPE_CD,
 SUM(NBM.DD_COMP_US_NET_PRICE_AMOUNT ) AS DD_COMP_US_NET_PRICE_AMT,
 SUM(NBM.DD_COMP_US_LIST_PRICE_AMOUNT ) AS DD_COMP_US_LIST_PRICE_AMT,
 SUM(NBM.DD_COMP_US_COST_AMOUNT ) AS DD_COMP_US_COST_AMT,
 SUM(NBM.DD_EXTENDED_QUANTITY ) AS DD_EXTENDED_QTY,
 SUM(NBM.DD_COMP_US_HOLD_NET_PRICE_AMT ) AS DD_COMP_US_HOLD_NET_PRICE_AMT,
 SUM(NBM.DD_COMP_US_HOLD_LIST_PRICE_AMT) AS DD_COMP_US_HOLD_LIST_PRICE_AMT,
 SUM(NBM.DD_COMP_US_HOLD_COST_AMOUNT ) AS DD_COMP_US_HOLD_COST_AMT,
 SUM(NBM.DD_EXTENDED_HOLD_QUANTITY ) AS DD_EXTENDED_HOLD_QTY,
 SUM(NBM.DD_COMP_US_STANDARD_PRICE_AMT ) AS DD_COMP_US_STANDARD_PRICE_AMT,
 SUM(NBM.TRADE_IN_AMOUNT ) AS TRADE_IN_AMT,
 NBCM.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
 NBM.DV_REVENUE_RECOGNITION_FLG	 /*Added as part of True Demand Booking Definition */,
 NBM.DV_NET_SPREAD_FLG 				 	/*Added as part of True Demand Booking Definition */,
 'CORE'  AS ACQUISITION_SOURCE_CD   /* Added as part of Qwin*/,
 NBM.DV_FMV_FLG/*FMV Q2FY15*/,
 NBM.ACQUISITION_ORDER_ORIGIN_CD,
 NBM.ACQUISITION_ROLE
 FROM
 {{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} NBM
 INNER JOIN
  {{ source('raw', 'N_BOOKINGS_CHANNEL_MEASURE') }} NBCM
 ON ( NBCM.BOOKINGS_MEASURE_KEY = NBM.BOOKINGS_MEASURE_KEY
 AND NBCM.BOOKINGS_PROCESS_DATE = NBM.BOOKINGS_PROCESS_DATE
 AND NBCM.BKGS_MEASURE_TRANS_TYPE_CODE = NBM.BKGS_MEASURE_TRANS_TYPE_CODE)
 INNER  JOIN
  {{ source('raw', 'R_PRODUCTS_FIN') }} NPT
 ON ( NBM.PRODUCT_KEY = NPT.ITEM_KEY )
 INNER JOIN
  {{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RFWTY
 ON (NBM.BOOKINGS_PROCESS_DATE = RFWTY.CALENDAR_DATE )
 WHERE
 COLLATE( NBM.DV_REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'  /*Modified as part of True Demand Booking Definition */
 AND RTRIM( NBM.DV_ATTRIBUTION_CD)  IN (COLLATE('ATTRIBUTED', 'en-ci-rtrim'), COLLATE('STANDALONE', 'en-ci-rtrim')) /*ICPM_FEBFY15*/
 AND COLLATE( NBM.RSTD_DEL_RECORD_FLG, 'en-ci-rtrim') = 'N'
 GROUP BY
 RFWTY.FISCAL_YEAR_WEEK_NUM_INT
 ,NBM.PRODUCT_KEY
 ,NBCM.PARTNER_SITE_PARTY_KEY
 ,NBM.SALES_TERRITORY_KEY
 ,NBM.ADJUSTMENT_TYPE_CODE
 ,NBM.SALES_CHANNEL_CODE
 ,NBM.SALES_CREDIT_TYPE_CODE
 ,NBM.IDE_ADJUSTMENT_CODE
 ,NBM.ADJUSTMENT_CODE
 ,NBM.BKGS_MEASURE_TRANS_TYPE_CODE
 ,NBM.CANCELLED_FLG
 ,NBM.ACQUISITION_FLG
 ,NBM.DISTRIBUTOR_OFFSET_FLG
 ,NBM.CORPORATE_BOOKINGS_FLG
 ,NBCM.CHANNEL_BOOKINGS_FLG
 ,NBM.OVERLAY_FLG
 ,NBM.IC_REVENUE_FLG
 ,NBM.CHARGES_FLG
 ,NBM.SALESREP_FLG
 ,NBM.MISC_FLG
 ,NBM.SERVICE_FLG
 ,NBM.INTERNATIONAL_DEMO_FLG
 ,NBM.REPLACEMENT_DEMO_FLG
 ,NBM.REVENUE_FLG
 ,NBM.RMA_FLG
 ,NBM.WIPS_ORIGINATOR_ID_INT
 /* The below commented for to increasing performance */
 /*,NSOFB.DV_DISCOUNT_BAND_CD 
 ,NSOFB.DV_ORDER_BAND_CD */
 ,
 CASE
  WHEN COLLATE(NBM.SERVICE_FLG, 'en-ci-rtrim') = 'N'
   THEN 'PRODUCT'
  WHEN COLLATE(NBM.SERVICE_FLG, 'en-ci-rtrim') = 'Y' AND RTRIM( NPT.BK_PRODUCT_TYPE_ID) NOT IN (COLLATE('TECHDOC', 'en-ci-rtrim'), COLLATE('TRAINING', 'en-ci-rtrim'))
   THEN 'CA SERVICE'
    ELSE 'OTHER SERVICE'
 END
  ,NBCM.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG
 ,NBM.DV_REVENUE_RECOGNITION_FLG /*Added as part of True Demand Booking Definition */
 ,NBM.DV_NET_SPREAD_FLG  /*Added as part of True Demand Booking Definition */
 ,NBM.DV_FMV_FLG/*FMV Q2FY15*/
 ,NBM.ACQUISITION_ORDER_ORIGIN_CD
 ,NBM.ACQUISITION_ROLE
{% endif %}